{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "ProjectContext",
  "description": "Identidad y configuración base del proyecto. Parte generada por 'context init', parte completada por el developer.",
  "type": "object",
  "required": ["id", "name", "description"],
  "properties": {
    "id": { "type": "string", "description": "Slug único del proyecto" },
    "name": { "type": "string" },
    "description": { "type": "string" },
    "version": { "type": "string" },
    "language": { "type": "string", "enum": ["es", "en"], "default": "es" },
    "domain": { "type": "string", "description": "Dominio de negocio: ej 'gestion-publica', 'ecommerce', 'saas'" },
    "agents": {
      "type": "array",
      "description": "Referencias a perfiles de agente que trabajan en este proyecto",
      "items": { "type": "string", "description": "Nombre del archivo en agents/ sin extensión" }
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "ContextTask",
  "description": "Tarea activa que el agente de IA debe ejecutar sobre el proyecto real.",
  "type": "object",
  "required": ["id", "title", "status", "scope", "done_when"],
  "properties": {
    "id": { "type": "string" },
    "title": { "type": "string", "maxLength": 80 },
    "created": { "type": "string", "format": "date" },
    "status": { "type": "string", "enum": ["active", "paused", "blocked"] },
    "context": {
      "type": "object",
      "properties": {
        "why": { "type": "string", "description": "Por qué es necesaria esta tarea" },
        "background": { "type": "string", "description": "Información relevante del proyecto para esta tarea" }
      }
    },
    "scope": {
      "type": "object",
      "description": "Qué puede y qué no puede tocar el agente",
      "properties": {
        "can_modify": { "type": "array", "items": { "type": "string" }, "description": "Globs de archivos modificables" },
        "cannot_modify": { "type": "array", "items": { "type": "string" } },
        "must_ask_before": { "type": "array", "items": { "type": "string" } }
      }
    },
    "steps": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Pasos sugeridos de implementación"
    },
    "done_when": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Criterios verificables de completitud"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "AgentProfile",
  "description": "Perfil de un agente de IA que trabaja en este proyecto. Define identidad, capacidades y restricciones.",
  "type": "object",
  "required": ["id", "name", "role", "capabilities", "restrictions"],
  "properties": {
    "id": { "type": "string" },
    "name": { "type": "string" },
    "role": {
      "type": "string",
      "enum": ["developer", "reviewer", "architect", "security-auditor", "qa-engineer", "devops", "doc-writer"],
      "description": "Rol del agente. Determina qué tipo de trabajo realiza."
    },
    "capabilities": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": ["read-code", "write-code", "run-tests", "run-commands", "read-docs", "write-docs", "security-review", "architecture-review"]
      }
    },
    "scope": {
      "type": "object",
      "properties": {
        "file_patterns": { "type": "array", "items": { "type": "string" }, "description": "Globs de archivos que puede modificar" },
        "excluded_patterns": { "type": "array", "items": { "type": "string" } }
      }
    },
    "restrictions": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Reglas explícitas de lo que el agente NO puede hacer"
    },
    "instructions": {
      "type": "string",
      "description": "Instrucciones adicionales en lenguaje natural para este agente en este proyecto"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "SignalFile",
  "description": "Archivo generado automáticamente por context scan. NUNCA editar manualmente.",
  "type": "object",
  "required": ["generatedAt", "source", "data"],
  "properties": {
    "generatedAt": { "type": "string", "format": "date-time" },
    "source": { "type": "string", "description": "Nombre del adaptador que generó este archivo" },
    "type": { "type": "string", "description": "Tipo de señal: stack, git, security, quality, lifecycle, privacy" },
    "data": { "type": "object", "description": "Datos del adaptador" }
  }
}
